Ah, I see! The recursive functions return `(value, pos)`, but in `parse_expression` and `parse_term`, I'm assigning the whole tuple to `left`:

```python
left = parse_term(tokens, pos)
```

So `left` becomes a tuple like `(2.0, 1)`. Then when I do `left = left + right`, I'm concatenating tuples instead of adding numbers.

I need to unpack the tuple:

```python
left, pos[0] = parse_term(tokens, pos)
```

Let me fix all the calls.

```file:calc.py
import re

class ExpressionError(Exception):
    pass

def tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        char = expr[i]

        if char.isspace():
            i += 1
            continue

        if char.isdigit() or char == '.':
            # Parse number
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if has_dot:
                        raise ExpressionError(f"Invalid number format at position {j}")
                    has_dot = True
                j += 1
            num_str = expr[i:j]
            try:
                tokens.append(float(num_str))
            except ValueError:
                raise ExpressionError(f"Invalid number '{num_str}'")
            i = j
        elif char in '+-*/()':
            tokens.append(char)
            i += 1
        else:
            raise ExpressionError(f"Unexpected character '{char}'")

    return tokens

def evaluate(expr: str) -> float:
    if not expr.strip():
        raise ExpressionError("Empty expression")

    tokens = tokenize(expr)
    pos = [0]  # Mutable index

    result, _ = parse_expression(tokens, pos)

    if pos[0] != len(tokens):
        raise ExpressionError(f"Unexpected token '{tokens[pos[0]]}' after expression")

    return result

def parse_expression(tokens, pos):
    """Handles + and -"""
    left, pos[0] = parse_term(tokens, pos)

    while pos[0] < len(tokens) and tokens[pos[0]] in ('+', '-'):
        op = tokens[pos[0]]
        pos[0] += 1
        if pos[0] >= len(tokens):
            raise ExpressionError(f"Trailing operator '{op}'")
        right, pos[0] = parse_term(tokens, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right

    return left, pos[0]

def parse_term(tokens, pos):
    """Handles * and /"""
    left, pos[0] = parse_factor(tokens, pos)

    while pos[0] < len(tokens) and tokens[pos[0]] in ('*', '/'):
        op = tokens[pos[0]]
        pos[0] += 1
        if pos[0] >= len(tokens):
            raise ExpressionError(f"Trailing operator '{op}'")
        right, pos[0] = parse_factor(tokens, pos)
        if op == '*':
            left = left * right
        else:
            if right == 0:
                raise ExpressionError("Division by zero")
            left = left / right

    return left, pos[0]

def parse_factor(tokens, pos):
    """Handles unary +/- and primary values (numbers, parens)"""
    if pos[0] >= len(tokens):
        raise ExpressionError("Unexpected end of expression")

    token = tokens[pos[0]]

    if token == '(':
        pos[0] += 1
        value, pos[0] = parse_expression(tokens, pos)
        if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
            raise ExpressionError("Unbalanced parentheses")
        pos[0] += 1  # Skip ')'
        return value, pos[0]
    elif isinstance(token, float):
        pos[0] += 1
        return token, pos[0]
    elif token == '-':
        pos[0] += 1
        value, pos[0] = parse_factor(tokens, pos)
        return -value, pos[0]
    elif token == '+':
        pos[0] += 1
        value, pos[0] = parse_factor(tokens, pos)
        return value, pos[0]
    else:
        raise ExpressionError(f"Unexpected token '{token}'")
